mapper.select:
select * from merchant_member
where merchant_user_id = #{merchantUserId}
  and user_id = #{userId}
  and deleted = 0
limit 1

mapper.insert:
insert into merchant_member (
    id, merchant_user_id, user_id, is_member, balance, created_time, update_time, deleted
) values (
    #{id}, #{merchantUserId}, #{userId}, #{isMember}, #{balance}, #{createdTime}, #{updateTime}, #{deleted}
)

mapper.update:
update merchant_member
set is_member = #{isMember},
    update_time = #{updateTime}
where merchant_user_id = #{merchantUserId}
  and user_id = #{userId}
  and deleted = 0

update merchant_member
set balance = balance - #{amount},
    update_time = #{updateTime}
where merchant_user_id = #{merchantUserId}
  and user_id = #{userId}
  and deleted = 0
  and is_member = 1
  and balance >= #{amount}

update merchant_member
set balance = balance + #{amount},
    update_time = #{updateTime}
where merchant_user_id = #{merchantUserId}
  and user_id = #{userId}
  and deleted = 0

update merchant_member
set is_member = 1,
    balance = balance + #{amount},
    update_time = #{updateTime}
where merchant_user_id = #{merchantUserId}
  and user_id = #{userId}
  and deleted = 0
